import type { GroundId, PartyId } from '@/components/world/scene';

import type { MapFrames, PlateMeta } from './layout';

/**
 * The expedition diorama's art, all generated by tools/art/diorama.py and
 * tools/art/characters.py (project-owned). One plate per Kilimanjaro zone.
 */
export type WorldZone = 'rainforest' | 'moorland' | 'desert' | 'snow';

export type Plate = {
  zone: WorldZone;
  image: number;
  meta: PlateMeta;
  /** The painted layer behind the plate's horizon. */
  far: number;
  /** Drifting particles: leaves and motes, heath seeds, dust, or snow. */
  particles: 'motes' | 'seeds' | 'dust' | 'snow';
  /** Colour of the air between the camera and the far ground. */
  haze: string;
};

