/** The old ground ids name the same zones; Everest's grounds borrow the nearest. */
export function zoneFor(ground: GroundId): WorldZone {
  if (ground === 'rainforest' || ground === 'forest' || ground === 'valley') return 'rainforest';
  if (ground === 'moorland') return 'moorland';
  if (ground === 'desert' || ground === 'rock') return 'desert';
  return 'snow';
}

